#include <iostream>
#include <vector>
#include <string>

using namespace std;

// Incrementa uma string representando um número inteiro positivo
void increment(string &s) {
    int n = s.size();
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] < '9') {
            s[i]++;
            return;
        }
        s[i] = '0';
    }
    s = "1" + s;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    string s = "";
    s.reserve(n);
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        s.push_back(c);
    }

    // Se o primeiro dígito for '0', não pode ser o início de A (já que A >= 1)
    // O problema garante 1 <= A, portanto s[0] != '0'.

    for (int len = 1; len <= n; ++len) {
        string cur = s.substr(0, len);
        if (cur[0] == '0') continue;

        int idx = len;
        bool ok = true;
        string next_val = cur;

        while (idx < n) {
            increment(next_val);
            int m = next_val.size();
            if (idx + m > n) {
                ok = false;
                break;
            }
            if (s.compare(idx, m, next_val) != 0) {
                ok = false;
                break;
            }
            idx += m;
        }

        if (ok && idx == n) {
            cout << cur << "\n";
            return 0;
        }
    }

    return 0;
}
